Step 1. Validate that the R script path and output path are provided and exist. If not, return False with an appropriate error message.
Step 2. Remove any existing file at the output path to ensure a fresh check.
Step 3. Record the start time and execute the R script using subprocess.Popen.
Step 4. Loop, checking every 0.5 seconds if the output file exists, until the specified duration expires.
Step 5. If the file is found before the duration ends, terminate the subprocess (if still running), return True with success message.
Step 6. If the duration expires and the file is not found, terminate the subprocess, return False with failure message.

### code
import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not os.path.isfile(r_script_path):
        return (False, "R script path does not exist.")
    if os.path.exists(output_path):
        os.remove(output_path)
    start_time = time.time()
    proc = subprocess.Popen(['Rscript', r_script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    while time.time() - start_time < duration:
        if os.path.exists(output_path):
            proc.terminate()
            return (True, "File generated successfully within the specified duration.")
        time.sleep(0.5)
    proc.terminate()
    return (False, "File not generated within the specified duration.")

