Step 1. Validate that the source folder exists; if not, return a failure dictionary with an appropriate message.
Step 2. Create the destination folder if it does not already exist.
Step 3. Use glob to get a list of all files in the source folder (non-recursive).
Step 4. Initialize an empty list for failed files.
Step 5. For each file in the source folder, construct the full path and run the gzip command as a background process using subprocess.Popen.
Step 6. After compression, move the resulting .gz file to the destination folder using shutil.move.
Step 7. If any step fails (compression or move), add the original filename to the failed_files list.
Step 8. After processing all files, determine success (True if no failed files, else False) and construct the message accordingly.
Step 9. Return the dictionary with success, message, and failed_files.

### code
import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': 'Source folder does not exist.', 'failed_files': []}
    os.makedirs(dst_folder, exist_ok=True)
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file_path in files:
        if os.path.isfile(file_path):
            filename = os.path.basename(file_path)
            try:
                proc = subprocess.Popen(['gzip', file_path])
                proc.wait()
                gz_file = file_path + '.gz'
                if os.path.exists(gz_file):
                    shutil.move(gz_file, os.path.join(dst_folder, filename + '.gz'))
                else:
                    failed_files.append(filename)
            except Exception:
                failed_files.append(filename)
    success = len(failed_files) == 0
    if success:
        message = 'All files compressed and moved successfully.'
    else:
        message = f'Failed to process {len(failed_files)} file(s).'
    return {'success': success, 'message': message, 'failed_files': failed_files}

